definition.frag:
float ang = radians(u_angle);
float amt = u_amount;
if (u_animate > 0.5) {
  float t = u_time * u_speed;
  float pulse = 0.5 + 0.5 * sin(t * 6.28318);
  float jitter = (noise(vec2(t * 4.0, 1.7)) - 0.5) * 0.3;
  amt *= clamp(pulse + jitter, 0.0, 1.0);
  ang += sin(t * 3.14159) * 0.2;
}
vec2 off = vec2(cos(ang), sin(ang)) * amt * u_texel;
vec4 r = texture(u_tex, v_st - off);
vec4 g = texture(u_tex, v_st);
vec4 b = texture(u_tex, v_st + off);
float a = max(g.a, max(r.a, b.a));
o = vec4(r.r, g.g, b.b, a);
